import { GoogleGenAI, GenerateContentResponse } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

const SYSTEM_INSTRUCTION = `
Eres el asistente virtual de "Gastronomía Martín Frances". 
Tu objetivo es ayudar a los usuarios con consultas sobre el chef Martín Frances, sus servicios de catering, menús para eventos y dar consejos básicos de cocina.
Siempre debes ser profesional, elegante y apasionado por la gastronomía.
Si te preguntan por recetas complejas, sugiere visitar la sección "Recetas Simples" de la web.
Menciona platos emblemáticos como el Cordero a la Cruz o Risotto de Hongos Silvestres si surge la oportunidad.
`;

export const getGeminiChatResponse = async (userMessage: string, history: { role: 'user' | 'model', content: string }[] = []) => {
  try {
    const chat = ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        ...history.map(h => ({ role: h.role === 'user' ? 'user' : 'model', parts: [{ text: h.content }] })),
        { role: 'user', parts: [{ text: userMessage }] }
      ],
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.7,
        topP: 0.95,
      }
    });

    const result = await chat;
    return result.text || "Lo siento, tuve un problema procesando tu consulta culinaria.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "En este momento no puedo responder, por favor intenta contactarnos por el formulario oficial.";
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { MessageCircle, X, Send, Utensils } from 'lucide-react';
import { getGeminiChatResponse } from '../services/geminiService';
import { ChatMessage } from '../types';

const ChatBot: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', content: '¡Hola! Soy el asistente virtual de Martín Frances. ¿En qué puedo ayudarte hoy?' }
  ]);
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    if (isOpen) scrollToBottom();
  }, [messages, isOpen]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMsg = input.trim();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', content: userMsg }]);
    setIsLoading(true);

    const response = await getGeminiChatResponse(userMsg, messages);
    setMessages(prev => [...prev, { role: 'model', content: response }]);
    setIsLoading(false);
  };

  return (
    <div className="fixed bottom-6 right-6 z-[100]">
      {/* Trigger Button */}
      <button
        onClick={() => setIsOpen(!isOpen)}
        className="h-14 w-14 rounded-full bg-amber-700 text-white shadow-lg flex items-center justify-center hover:bg-amber-800 transition-all hover:scale-110 active:scale-95"
      >
        {isOpen ? <X className="h-6 w-6" /> : <MessageCircle className="h-6 w-6" />}
      </button>

      {/* Chat Window */}
      {isOpen && (
        <div className="absolute bottom-20 right-0 w-[350px] sm:w-[400px] h-[500px] bg-white rounded-2xl shadow-2xl flex flex-col overflow-hidden border border-stone-200 animate-in slide-in-from-bottom-5 fade-in duration-300">
          {/* Header */}
          <div className="bg-amber-700 p-4 text-white flex items-center justify-between">
            <div className="flex items-center space-x-3">
              <div className="bg-white/20 p-2 rounded-full">
                <Utensils className="h-5 w-5" />
              </div>
              <div>
                <p className="font-bold text-sm">Chef Asistente</p>
                <p className="text-[10px] opacity-80">En línea para ayudarte</p>
              </div>
            </div>
            <button onClick={() => setIsOpen(false)}>
              <X className="h-5 w-5 opacity-70 hover:opacity-100" />
            </button>
          </div>

          {/* Messages Area */}
          <div className="flex-grow overflow-y-auto p-4 space-y-4 bg-stone-50">
            {messages.map((msg, idx) => (
              <div
                key={idx}
                className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
              >
                <div
                  className={`max-w-[80%] px-4 py-2 rounded-2xl text-sm ${
                    msg.role === 'user'
                      ? 'bg-amber-700 text-white rounded-br-none'
                      : 'bg-white border border-stone-200 text-stone-800 rounded-bl-none shadow-sm'
                  }`}
                >
                  {msg.content}
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex justify-start">
                <div className="bg-white border border-stone-200 p-3 rounded-2xl rounded-bl-none">
                  <div className="flex space-x-1">
                    <div className="h-1.5 w-1.5 bg-stone-400 rounded-full animate-bounce"></div>
                    <div className="h-1.5 w-1.5 bg-stone-400 rounded-full animate-bounce delay-75"></div>
                    <div className="h-1.5 w-1.5 bg-stone-400 rounded-full animate-bounce delay-150"></div>
                  </div>
                </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>

          {/* Input Area */}
          <div className="p-4 bg-white border-t border-stone-100 flex items-center space-x-2">
            <input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSend()}
              placeholder="Escribe tu consulta..."
              className="flex-grow px-4 py-2 bg-stone-100 border-none rounded-full text-sm focus:ring-2 focus:ring-amber-500 outline-none"
            />
            <button
              onClick={handleSend}
              disabled={isLoading}
              className="p-2 bg-amber-700 text-white rounded-full hover:bg-amber-800 disabled:opacity-50 transition-colors"
            >
              <Send className="h-4 w-4" />
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default ChatBot;

